const [, zone] = msg.topic.split('/');
const payload = typeof msg.payload === 'object' ? msg.payload : JSON.parse(msg.payload);
msg.payload = {
    zone,
    density_count: Number(payload.density_count),
    risk_level: payload.risk_level,
    speed: Number(payload.speed),
    timestamp: payload.timestamp,
    event_type: payload.event_type || null,
    test_run_id: payload.test_run_id || null,
    source_topic: msg.topic
};
return msg;

